import Complex128Array = require( '@stdlib/array/complex128' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import zgbmv = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 10 );
	const A = new Complex128Array( 20 );
	const alpha = new Complex128( 1.0, 0.0 );
	const beta = new Complex128( 1.0, 0.0 );

	zgbmv( 'row-major', 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 10 );
	const A = new Complex128Array( 20 );
	const alpha = new Complex128( 0.5, 0.5 );
	const beta = new Complex128( 0.5, -0.5 );

	zgbmv( 10, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( true, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( false, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( null, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( undefined, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( [], 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( {}, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
	zgbmv( ( x: number ): number => x, 'no-transpose', 10, 10, 1, 1, alpha, A, 10, x, 1, beta, y, 1 ); // $ExpectError
}

